332|## Custom ShaderPass
333|
334|Create your own post-processing effects.
335|
336|```javascript
337|import { ShaderPass } from "three/addons/postprocessing/ShaderPass.js";
338|
339|const CustomShader = {
340|  uniforms: {
341|    tDiffuse: { value: null }, // Required: input texture
342|    time: { value: 0 },
343|    intensity: { value: 1.0 },
344|  },
345|  vertexShader: `
346|    varying vec2 vUv;
347|
348|    void main() {
349|      vUv = uv;
350|      gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
351|    }
352|  `,
353|  fragmentShader: `
354|    uniform sampler2D tDiffuse;
355|    uniform float time;
356|    uniform float intensity;
357|    varying vec2 vUv;
358|
359|    void main() {
360|      vec2 uv = vUv;
361|
362|      // Wave distortion
363|      uv.x += sin(uv.y * 10.0 + time) * 0.01 * intensity;
364|
365|      vec4 color = texture2D(tDiffuse, uv);
366|      gl_FragColor = color;
367|    }
368|  `,
369|};
370|
371|const customPass = new ShaderPass(CustomShader);
372|composer.addPass(customPass);
373|
374|// Update in animation loop
375|customPass.uniforms.time.value = clock.getElapsedTime();
376|```
